        "center_first_v1" => Ok(if legal.contains(&4) { 4 } else { legal[0] }),
        "corner_first_v1" => Ok(first_preferred(&legal, &CORNERS).unwrap_or(legal[0])),
        "edge_first_v1" => Ok(first_preferred(&legal, &EDGES).unwrap_or(legal[0])),
        "win_block_center_v1" => Ok(winning_position(board, player)
            .or_else(|| winning_position(board, opponent(player)))
            .or_else(|| legal.contains(&4).then_some(4))
            .or_else(|| first_preferred(&legal, &CORNERS))
            .unwrap_or(legal[0])),
