    }
}

fn first_preferred(legal: &[usize], preferred: &[usize]) -> Option<usize> {
    preferred.iter().copied().find(|pos| legal.contains(pos))
}

fn seeded_order(values: &[usize], seed: i64, ply: usize, namespace: &str) -> Vec<usize> {
    let mut ordered = values.to_vec();
    ordered.sort_by_key(|value| {
        let mut hasher = Sha256::new();
        hasher.update(format!("{namespace}:{seed}:{ply}:{value}").as_bytes());
        format!("{:x}", hasher.finalize())
    });
    ordered
}

fn minimax_position(board: &[String], player: &str) -> Result<usize, String> {
    let legal = legal_positions(board);
    if legal.is_empty() {
        return Err("no legal positions".to_string());
    }
    let mut best_pos = legal[0];
    let mut best_score = i32::MIN;
    for pos in legal {
        let mut next = board.to_vec();
        next[pos] = player.to_string();
        let score = minimax_score(&next, opponent(player), player);
        if score > best_score {
            best_score = score;
            best_pos = pos;
        }
    }
    Ok(best_pos)
}

fn minimax_score(board: &[String], turn: &str, root_player: &str) -> i32 {
    if let Some(winner) = winner_for(board) {
        return if winner == root_player { 1 } else { -1 };
    }
    let legal = legal_positions(board);
    if legal.is_empty() {
        return 0;
    }

    let maximizing = turn == root_player;
    let mut best = if maximizing { i32::MIN } else { i32::MAX };
    for pos in legal {
        let mut next = board.to_vec();
        next[pos] = turn.to_string();
        let score = minimax_score(&next, opponent(turn), root_player);
        if maximizing {
            best = best.max(score);
        } else {
            best = best.min(score);
        }
    }
    best
}

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::io::{self, Read};

const WIN_LINES: [(usize, usize, usize); 8] = [
    (0, 1, 2),
    (3, 4, 5),
    (6, 7, 8),
    (0, 3, 6),
    (1, 4, 7),
    (2, 5, 8),
    (0, 4, 8),
    (2, 4, 6),
];
const CORNERS: [usize; 4] = [0, 2, 6, 8];
const EDGES: [usize; 4] = [1, 3, 5, 7];
const MIRROR_ORDER: [usize; 9] = [8, 6, 2, 0, 4, 7, 5, 3, 1];

#[derive(Clone, Debug, Deserialize)]
struct Action {
    player: String,
    position: i64,
}

#[derive(Clone, Debug, Deserialize)]
struct PolicySpec {
    policy_id: Option<String>,
}

#[derive(Debug, Deserialize)]
struct Scenario {
    scenario_id: String,
    #[serde(default)]
    seed: i64,
    #[serde(default = "default_max_plies")]
    max_plies: usize,
    #[serde(default)]
    opening_moves: Vec<Action>,
    agent_0_policy_id: Option<String>,
    agent_1_policy_id: Option<String>,
    x_policy_id: Option<String>,
    o_policy_id: Option<String>,
    agent_0_policy: Option<PolicySpec>,
    agent_1_policy: Option<PolicySpec>,
    x_policy: Option<PolicySpec>,
    o_policy: Option<PolicySpec>,
}

#[derive(Serialize)]
struct Output {
    events: Vec<String>,
}

#[derive(Clone)]
struct Engine {
    board: Vec<String>,
    turn: String,
    winner: Option<String>,
    step_index: usize,
    ply: usize,
    terminated: bool,
    truncated: bool,
    events: Vec<String>,
}

fn default_max_plies() -> usize {
    9
}

impl Engine {
    fn new() -> Self {
        Self {
            board: vec![String::new(); 9],
            turn: "X".to_string(),
            winner: None,
            step_index: 0,
            ply: 0,
            terminated: false,
            truncated: false,
            events: Vec::new(),
        }
    }

    fn reset(&mut self, scenario_id: &str) {
        self.board = vec![String::new(); 9];
        self.turn = "X".to_string();
        self.winner = None;
        self.step_index = 0;
        self.ply = 0;
        self.terminated = false;
        self.truncated = false;
        self.events.clear();
        self.events.push(format!("GameStarted({scenario_id})"));
    }

    fn step(&mut self, action: Action) {
        if self.terminated || self.truncated {
            self.events.push("game is already over".to_string());
            return;
        }

        let player = action.player;
        let position = action.position;
        if player != self.turn {
            self.events.push(format!("expected {} to move", self.turn));
            return;
        }
        if !(0..9).contains(&position) {
            self.events.push("position out of range".to_string());
            return;
        }
        let pos = position as usize;
        if !self.board[pos].is_empty() {
            self.events.push("position already occupied".to_string());
            return;
        }

        self.board[pos] = player.clone();
        self.ply += 1;
        self.step_index += 1;
        self.events.push(format!("MoveApplied({player},{pos})"));

        if let Some(winner) = winner_for(&self.board) {
            self.winner = Some(winner.clone());
            self.terminated = true;
            self.events.push(format!("GameEnded({winner},win)"));
        } else if self.board.iter().all(|cell| !cell.is_empty()) {
            self.winner = Some("draw".to_string());
            self.terminated = true;
            self.events.push("GameEnded(draw,draw)".to_string());
        } else {
            self.turn = if player == "X" { "O" } else { "X" }.to_string();
            self.events.push(format!("TurnStarted({})", self.turn));
        }
    }
}

fn main() {
    if let Err(err) = run() {
        eprintln!("{err}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), String> {
    let mut input = String::new();
    io::stdin()
        .read_to_string(&mut input)
        .map_err(|err| err.to_string())?;
    let scenario: Scenario = serde_json::from_str(&input).map_err(|err| err.to_string())?;
    let events = run_scenario(&scenario)?;
    let stdout = serde_json::to_string(&Output { events }).map_err(|err| err.to_string())?;
    println!("{stdout}");
    Ok(())
}

fn run_scenario(task: &Scenario) -> Result<Vec<String>, String> {
    let x_policy = policy_for_x(task)?;
    let o_policy = policy_for_o(task)?;

    let mut engine = Engine::new();
    engine.reset(&task.scenario_id);

    for action in &task.opening_moves {
        engine.step(action.clone());
    }

    let mut plies = 0usize;
    while !engine.terminated && !engine.truncated && plies < task.max_plies {
        let policy_id = if engine.turn == "X" {
            x_policy.as_str()
        } else {
            o_policy.as_str()
        };
        let position = choose_position(policy_id, &engine.board, &engine.turn, task.seed, plies)?;
        engine.step(Action {
            player: engine.turn.clone(),
            position: position as i64,
        });
        plies += 1;
    }

    if !engine.terminated && !engine.truncated {
        engine
            .events
            .push(format!("RolloutStopped(max_plies={})", task.max_plies));
    }

    Ok(engine.events)
}

fn policy_for_x(task: &Scenario) -> Result<String, String> {
    task.agent_0_policy
        .as_ref()
        .and_then(|spec| spec.policy_id.clone())
        .or_else(|| {
            task.x_policy
                .as_ref()
                .and_then(|spec| spec.policy_id.clone())
        })
        .or_else(|| task.agent_0_policy_id.clone())
        .or_else(|| task.x_policy_id.clone())
        .ok_or_else(|| "no policy spec for agent_0".to_string())
}

fn policy_for_o(task: &Scenario) -> Result<String, String> {
    task.agent_1_policy
        .as_ref()
        .and_then(|spec| spec.policy_id.clone())
        .or_else(|| {
            task.o_policy
                .as_ref()
                .and_then(|spec| spec.policy_id.clone())
        })
        .or_else(|| task.agent_1_policy_id.clone())
        .or_else(|| task.o_policy_id.clone())
        .ok_or_else(|| "no policy spec for agent_1".to_string())
}

fn winner_for(board: &[String]) -> Option<String> {
    for (a, b, c) in WIN_LINES {
        if !board[a].is_empty() && board[a] == board[b] && board[b] == board[c] {
            return Some(board[a].clone());
        }
    }
    None
}

fn legal_positions(board: &[String]) -> Vec<usize> {
    board
        .iter()
        .enumerate()
        .filter_map(|(index, value)| if value.is_empty() { Some(index) } else { None })
        .collect()
}

fn winning_position(board: &[String], player: &str) -> Option<usize> {
    for (a, b, c) in WIN_LINES {
        let line = [a, b, c];
        let values = [&board[a], &board[b], &board[c]];
        let player_count = values
            .iter()
            .filter(|value| value.as_str() == player)
            .count();
        let empty_count = values.iter().filter(|value| value.is_empty()).count();
        if player_count == 2 && empty_count == 1 {
            for (index, value) in values.iter().enumerate() {
                if value.is_empty() {
                    return Some(line[index]);
                }
            }
        }
    }
    None
}

